package main

import (
	"fmt"
	"slices"
	"strconv"
	"strings"
	"unicode"
	"unicode/utf8"
)

type diffKind int

const (
	diffEqual diffKind = iota
	diffDelete
	diffInsert
)

type diffOp struct {
	kind diffKind
	line string
}

const (
	// diffContext is how many unchanged lines frame each change, as in
	// `diff -u` and `git diff`: enough to place a one-line change without
	// reading the file it came from.
	diffContext = 3

	// maxDiffLines caps how much of a diff one stale report prints. A file
	// regenerated by another servo version can differ on nearly every line,
	// and thousands of lines of that in a CI log bury the one line of the
	// report that matters — the command to run.
	maxDiffLines = 400

	// maxEdits bounds the search for a shortest edit script: past this many
	// differing lines the middle of the file is reported as replaced
	// wholesale, which is what a diff that large amounts to anyway. It is
	// what keeps both the time and the memory of a diff bounded however
	// large the generated file grows.
	maxEdits = 1000

	// maxHeadingLen keeps a hunk heading — the declaration line a change
	// sits under — to one terminal line, as git does.
	maxHeadingLen = 80
)

// unifiedDiff renders the difference between oldContent and newContent as
// a unified diff labelled path, for `servo check` to print alongside its
// stale-file error: a hunk per change, headed with its line numbers on both
// sides and the declaration line its first change sits under, the changed
// lines inside three lines of unchanged context.
//
// The context and the heading are the point. A bare `+	_ =
// a.stopIssuer(ctx)` cannot be told apart from the twenty other stop calls
// in a generated file, while the same line under
// `@@ -727,6 +727,7 @@ func (a *App) rollbackFromCache(...)` says which
// rollback path a merge dropped it from.
func unifiedDiff(oldContent, newContent, path string) string {
	oldLines, newLines := strings.Split(oldContent, "\n"), strings.Split(newContent, "\n")
	// A final newline leaves an empty string after the last line, which is
	// not a line: it would show as context under every change at the end of
	// the file. Unless only one side has it, in which case it is exactly the
	// difference and has to stay.
	if oldLines[len(oldLines)-1] == "" && newLines[len(newLines)-1] == "" {
		oldLines, newLines = oldLines[:len(oldLines)-1], newLines[:len(newLines)-1]
	}

	var b strings.Builder
	fmt.Fprintf(&b, "--- %s (committed)\n+++ %s (fresh)\n", path, path)
	hunks := diffHunks(diffLines(oldLines, newLines), diffContext)
	budget := maxDiffLines
	// truncated ends the report once the budget is spent, saying how much
	// was left out: the rest of hunk i from op j on, and every later hunk.
	truncated := func(i, j int) string {
		rest := len(hunks[i].ops) - j
		for _, later := range hunks[i+1:] {
			rest += len(later.ops)
		}
		fmt.Fprintf(&b, "... %d more lines of diff not shown — regenerate, and `git diff` shows the whole change\n", rest)
		return b.String()
	}
	for i, h := range hunks {
		if budget == 0 {
			return truncated(i, 0)
		}
		fmt.Fprintf(&b, "@@ -%s +%s @@", hunkRange(h.oldStart, h.oldCount), hunkRange(h.newStart, h.newCount))
		if heading := hunkHeading(oldLines, h.oldChange); heading != "" {
			b.WriteString(" " + heading)
		}
		b.WriteString("\n")
		for j, op := range h.ops {
			if budget == 0 {
				return truncated(i, j)
			}
			budget--
			b.WriteString(diffMarks[op.kind] + op.line + "\n")
		}
	}
	return b.String()
}

// diffMarks is the unified-diff prefix of each kind of line.
var diffMarks = [...]string{diffEqual: " ", diffDelete: "-", diffInsert: "+"}

// hunk is one contiguous run of diff lines: changes plus the context around
// them. Starts are 0-based line indexes; counts are lines on that side.
type hunk struct {
	oldStart, oldCount int
	newStart, newCount int
	// oldChange is the old-side index of the hunk's first changed line —
	// where its heading is looked for, rather than above the leading
	// context, so a `func` line inside that context still names the change.
	oldChange int
	ops       []diffOp
}

// diffHunks groups ops into hunks with context unchanged lines around each
// change. Two changes closer than twice the context share a hunk, since
// their contexts would otherwise overlap — the rule `diff -u` follows.
func diffHunks(ops []diffOp, context int) []hunk {
	// oldAt[i] and newAt[i] are the line indexes ops[i] starts at.
	oldAt, newAt := make([]int, len(ops)+1), make([]int, len(ops)+1)
	for i, op := range ops {
		oldAt[i+1], newAt[i+1] = oldAt[i], newAt[i]
		if op.kind != diffInsert {
			oldAt[i+1]++
		}
		if op.kind != diffDelete {
			newAt[i+1]++
		}
	}

	var hunks []hunk
	for i := 0; i < len(ops); {
		for i < len(ops) && ops[i].kind == diffEqual {
			i++
		}
		if i == len(ops) {
			break
		}
		start, end := max(0, i-context), i
		for {
			for end < len(ops) && ops[end].kind != diffEqual {
				end++
			}
			next := end
			for next < len(ops) && ops[next].kind == diffEqual {
				next++
			}
			if next < len(ops) && next-end <= 2*context {
				end = next
				continue
			}
			end = min(len(ops), end+context)
			break
		}
		hunks = append(hunks, hunk{
			oldStart: oldAt[start], oldCount: oldAt[end] - oldAt[start],
			newStart: newAt[start], newCount: newAt[end] - newAt[start],
			oldChange: oldAt[i],
			ops:       ops[start:end],
		})
		i = end
	}
	return hunks
}

// hunkRange renders one side of a hunk header the way `diff -u` does: a
// 1-based start and a count, the count left out when it is one, and for an
// empty side the line the change comes after.
func hunkRange(start, count int) string {
	switch count {
	case 0:
		return strconv.Itoa(start) + ",0"
	case 1:
		return strconv.Itoa(start + 1)
	}
	return strconv.Itoa(start+1) + "," + strconv.Itoa(count)
}

// hunkHeading is the nearest line above index before that starts a
// declaration, recognised the way git's default does it: a line beginning
// with a letter or an underscore. In gofmt'd Go that is the `func`, `type`,
// `var` or `const` line a change sits under, or "" at the top of the file.
//
// git looks above the hunk's leading context, so a change in the first few
// lines of a function is headed with the function before it. Searching from
// the change itself names the right one; in generated code, where every
// rollback path is the same few lines under a different name, that is the
// whole value of the heading.
func hunkHeading(lines []string, before int) string {
	for i := min(before, len(lines)) - 1; i >= 0; i-- {
		r, _ := utf8.DecodeRuneInString(lines[i])
		if r != '_' && !unicode.IsLetter(r) {
			continue
		}
		heading := strings.TrimRightFunc(lines[i], unicode.IsSpace)
		if len(heading) > maxHeadingLen {
			cut := maxHeadingLen
			for cut > 0 && !utf8.RuneStart(heading[cut]) {
				cut--
			}
			heading = heading[:cut]
		}
		return heading
	}
	return ""
}

// diffLines is the line diff behind unifiedDiff: every line of a and b,
// each marked equal, deleted or inserted, in order.
//
// The common prefix and suffix are trimmed first, in linear time: a
// regenerated file differs from its committed copy in a few places, and
// trimming hands the core only the span between the first and the last of
// them. The core is Myers' algorithm (appendEdits), whose cost follows the
// number of differing lines rather than the length of the file — the
// quadratic table it replaces cost three gigabytes for a twenty-thousand
// line file with a single changed line in the middle.
func diffLines(a, b []string) []diffOp {
	prefix := 0
	for prefix < len(a) && prefix < len(b) && a[prefix] == b[prefix] {
		prefix++
	}
	suffix := 0
	for suffix < len(a)-prefix && suffix < len(b)-prefix && a[len(a)-1-suffix] == b[len(b)-1-suffix] {
		suffix++
	}

	ops := make([]diffOp, 0, len(a)+len(b)-prefix-suffix)
	for _, line := range a[:prefix] {
		ops = append(ops, diffOp{diffEqual, line})
	}
	ops = appendEdits(ops, a[prefix:len(a)-suffix], b[prefix:len(b)-suffix])
	for _, line := range a[len(a)-suffix:] {
		ops = append(ops, diffOp{diffEqual, line})
	}
	return ops
}

// appendEdits appends a shortest edit script turning a into b, using
// Myers' greedy algorithm: it explores edit distances d = 0, 1, 2, … and
// stops at the first that reaches the end of both sides, so its time is
// O((N+M)·D) and the trace it keeps to recover the path is O(D²), for D
// differing lines.
//
// Past maxEdits it stops looking and reports a deleted and b inserted
// whole. That is never wrong, only less minimal, and a diff that large is
// read as "this file changed shape", not line by line.
func appendEdits(ops []diffOp, a, b []string) []diffOp {
	n, m := len(a), len(b)
	limit := min(n+m, maxEdits)
	// v[offset+k] is the furthest x reached so far on diagonal k = x - y.
	// Step d reads diagonals k±1 for every k in [-d, d], hence the margin.
	offset := limit + 1
	v := make([]int, 2*limit+3)
	// trace[d] is v's window [-d, d] as it stood when step d began, which
	// is everything the walk back from the end needs to know about step d.
	var trace [][]int
	for d := 0; d <= limit; d++ {
		trace = append(trace, slices.Clone(v[offset-d:offset+d+1]))
		for k := -d; k <= d; k += 2 {
			var x int
			if k == -d || (k != d && v[offset+k-1] < v[offset+k+1]) {
				x = v[offset+k+1] // down from diagonal k+1: insert b[y-1]
			} else {
				x = v[offset+k-1] + 1 // right from diagonal k-1: delete a[x-1]
			}
			y := x - k
			for x < n && y < m && a[x] == b[y] {
				x++
				y++
			}
			v[offset+k] = x
			if x >= n && y >= m {
				return appendPath(ops, a, b, trace)
			}
		}
	}
	for _, line := range a {
		ops = append(ops, diffOp{diffDelete, line})
	}
	for _, line := range b {
		ops = append(ops, diffOp{diffInsert, line})
	}
	return ops
}

// appendPath recovers the edit script appendEdits found by walking its
// trace back from the end of both sides, and appends it in order.
func appendPath(ops []diffOp, a, b []string, trace [][]int) []diffOp {
	x, y := len(a), len(b)
	var rev []diffOp
	for d := len(trace) - 1; d > 0; d-- {
		v := trace[d] // v[d+k] is the furthest x on diagonal k after step d-1
		k := x - y
		prevK := k - 1
		if k == -d || (k != d && v[d+k-1] < v[d+k+1]) {
			prevK = k + 1
		}
		prevX := v[d+prevK]
		prevY := prevX - prevK
		// The snake of equal lines that followed the edit, walked backwards.
		for x > prevX && y > prevY {
			x--
			y--
			rev = append(rev, diffOp{diffEqual, a[x]})
		}
		if x == prevX {
			y--
			rev = append(rev, diffOp{diffInsert, b[y]})
		} else {
			x--
			rev = append(rev, diffOp{diffDelete, a[x]})
		}
	}
	// Step 0 is the snake from the origin, before the first edit.
	for x > 0 && y > 0 {
		x--
		y--
		rev = append(rev, diffOp{diffEqual, a[x]})
	}
	slices.Reverse(rev)
	return append(ops, rev...)
}
